<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { CalendarDays, Download, Clock3, MapPin, UserRound } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import AppModal from '../components/AppModal.vue'
import { api, query } from '../lib/api'
import { csvDownload } from '../lib/format'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'

interface Lesson { sectionId: string; courseTitle: string; teacherName: string; room: string; weekday: number; startPeriod: number; endPeriod: number; startWeek: number; endWeek: number }
const workspace = useWorkspace(), { loading, error, run } = useAsync()
const lessons = ref<Lesson[]>([]), week = ref(1), detail = ref<Lesson>(), periods = Array.from({ length: 14 }, (_, i) => i + 1), weekdays = ['星期一', '星期二', '星期三', '星期四', '星期五', '星期六', '星期日']
const shown = computed(() => lessons.value.filter(item => item.startWeek <= week.value && item.endWeek >= week.value))

async function load() { await run(() => api<{ termId: string; items: Lesson[] }>('/student/timetable' + query({ termId: workspace.termId })), result => { lessons.value = result.items }) }
watch(() => workspace.termId, load, { immediate: true })
function download() { csvDownload(`课序-${workspace.currentTerm?.name || '我的课表'}.csv`, [['课程', '教学班', '教师', '星期', '起始节次', '结束节次', '开始周', '结束周', '地点'], ...lessons.value.map(item => [item.courseTitle, item.sectionId, item.teacherName, item.weekday, item.startPeriod, item.endPeriod, item.startWeek, item.endWeek, item.room])]) }
</script>
<template><PageHeading eyebrow="MAKE ROOM FOR WHAT MATTERS" title="我的课表" description="把时间安排得刚刚好，给专注学习留出空间。"><select v-model="workspace.termId" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select><button class="button button-secondary" :disabled="!lessons.length" @click="download"><Download :size="14"/>导出课表</button></PageHeading><section class="card"><div class="card-header"><div><h2>{{ workspace.currentTerm?.name }} · 每周课表</h2><p>只显示当前已选的教学班 · 点击课程查看完整安排</p></div><div class="row"><CalendarDays :size="15" class="muted"/><select v-model="week" class="select-control" aria-label="选择教学周"><option v-for="n in 30" :key="n" :value="n">第 {{ n }} 周</option></select></div></div><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load"/><StatePanel v-else-if="!lessons.length" title="课表还是一张干净的画布" description="选课成功后，课程安排会自动出现在这里。"><RouterLink to="/student/catalog" class="button button-secondary">前往选课中心</RouterLink></StatePanel><template v-else><div v-if="!shown.length" class="notice-banner" style="margin:18px">第 {{ week }} 周没有课程安排，可以切换其他教学周查看。</div><div class="schedule-wrap"><div class="schedule-grid"><div class="schedule-head" style="grid-column:1;grid-row:1">节次</div><div v-for="(day, i) in weekdays" :key="day" class="schedule-head" :style="{ gridColumn: i + 2, gridRow: 1 }">{{ day }}<small>{{ i > 4 ? 'WEEKEND' : 'LEARNING DAY' }}</small></div><template v-for="period in periods" :key="period"><div class="schedule-time" :style="{ gridColumn: 1, gridRow: period + 1 }"><div>第 {{ period }} 节</div></div><div v-for="day in 7" :key="day" class="schedule-cell" :style="{ gridColumn: day + 1, gridRow: period + 1 }"/></template><button v-for="(lesson, i) in shown" :key="lesson.sectionId + '-' + i" class="schedule-event" :class="`color-${i % 4}`" :style="{ gridColumn: lesson.weekday + 1, gridRow: `${lesson.startPeriod + 1} / span ${lesson.endPeriod - lesson.startPeriod + 1}`, zIndex: 1, margin: '4px', width: 'calc(100% - 8px)' }" :aria-label="`${lesson.courseTitle}，${weekdays[lesson.weekday - 1]}，${lesson.startPeriod}到${lesson.endPeriod}节，${lesson.room}`" @click="detail = lesson"><strong>{{ lesson.courseTitle }}</strong><small>{{ lesson.room }}<br>{{ lesson.teacherName }}<br>{{ lesson.startPeriod }}—{{ lesson.endPeriod }}节</small></button></div></div><div class="card-footer"><span>第 {{ week }} 周 · {{ shown.length }} 段课程安排</span><span>按节次与教学周显示，具体作息时间以学校通知为准。</span></div></template></section><AppModal :open="!!detail" title="课程安排" @close="detail = undefined"><template v-if="detail"><h3 style="font-size:21px">{{ detail.courseTitle }}</h3><p class="muted mono mt-12">{{ detail.sectionId }}</p><dl class="detail-grid"><div><dt>授课教师</dt><dd><UserRound :size="12"/> {{ detail.teacherName }}</dd></div><div><dt>教室</dt><dd><MapPin :size="12"/> {{ detail.room }}</dd></div><div><dt>上课时间</dt><dd><Clock3 :size="12"/> {{ weekdays[detail.weekday - 1] }} {{ detail.startPeriod }}—{{ detail.endPeriod }}节</dd></div><div><dt>教学周</dt><dd>第 {{ detail.startWeek }}—{{ detail.endWeek }} 周</dd></div></dl></template><template #footer><button class="button button-secondary" @click="detail = undefined">知道了</button></template></AppModal></template>
